function validate([candies, num_people]) {
  if (!Number.isInteger(candies) || candies < 1 || candies > 1e9) return 'candies must be a whole number from 1 to 10^9.';
  if (!Number.isInteger(num_people) || num_people < 1 || num_people > 1000) return 'num_people must be a whole number from 1 to 1000.';
  return null;
}

