function distributeCandies(candies, num_people) {
  const result = new Array(num_people).fill(0);
  let gift = 1;
  let person = 0;
  while (candies > 0) {
    const given = Math.min(gift, candies);
    result[person] += given;
    candies -= given;
    gift++;
    person = (person + 1) % num_people;
  }
  return result;
}

