function distributeCandies(candies, num_people) {
  // Closed form: count the full gifts k with 1 + 2 + ... + k <= candies, then sum each person's share.
  let k = Math.floor((Math.sqrt(8 * candies + 1) - 1) / 2);
  while (k * (k + 1) / 2 > candies) k--;
  while ((k + 1) * (k + 2) / 2 <= candies) k++;
  const out = [];
  for (let i = 0; i < num_people; i++) {
    // Person i receives gifts i+1, i+1+n, i+1+2n, ... that are at most k.
    const rounds = k >= i + 1 ? Math.floor((k - (i + 1)) / num_people) + 1 : 0;
    out.push(rounds * (i + 1) + num_people * rounds * (rounds - 1) / 2);
  }
  const rest = candies - k * (k + 1) / 2;
  out[k % num_people] += rest;
  return out;
}

