function generate(rand, size) {
  if (size === 'large') {
    const candies = 1000000000 - Math.floor(rand() * 1000000);
    const num_people = 1 + Math.floor(rand() * 1000);
    return [candies, num_people];
  }
  const candies = 1 + Math.floor(rand() * (rand() < 0.5 ? 12 : 120));
  const num_people = 1 + Math.floor(rand() * (rand() < 0.5 ? 4 : 12));
  return [candies, num_people];
}
